import { expect, test } from "bun:test";

import { validateFixture } from "../src/validate.ts";

const VALID = {
  schema_version: 1,
  family_id: "fam-syn-x",
  split: "dev",
  synthetic: true,
  root: { kind: "synthetic", id: "x" },
};

test("a conforming fixture validates with no errors", () => {
  expect(validateFixture(VALID)).toEqual({ ok: true, errors: [] });
});

test("a non-1 schema_version is rejected", () => {
  expect(validateFixture({ ...VALID, schema_version: 2 })).toEqual({
    ok: false,
    errors: ["bad_schema_version"],
  });
});

test("a non-object input is rejected", () => {
  expect(validateFixture("nope")).toEqual({ ok: false, errors: ["not_object"] });
});
